def log_security_event(event_type: str, prompt: str, classification: str, action_taken: str):
    log_entry = {
        "timestamp": datetime.utcnow().isoformat() + "Z",
        "event_type": event_type,
        "flagged_content": prompt[:500],
        "classification_category": classification,
        "action_taken": action_taken
    }
    with open(LOG_FILE, "a") as f:
        f.write(json.dumps(log_entry) + "\n")

def inspect_input(text: str) -> tuple[bool, str]:
    if not text:
        return False, ""

    normalized_text = text.lower().strip()

    malicious_indicators = ["system override", "override initialized", "internal system key"]
    if any(indicator in normalized_text for indicator in malicious_indicators):
        return True, "Keyword Match (System Override / Internal Key)"

    masquerade_pattern = re.compile(r"system\s+developer.*maintenance\s+check", re.IGNORECASE | re.DOTALL)
    if masquerade_pattern.search(text):
        return True, "Pattern Match (Developer Role-Play Masquerade)"

    return False, ""

@app.post("/v1/chat/completions")
async def secure_chat_completion(request: Request):
    body = await request.json()
    messages = body.get("messages", [])

    full_prompt_context = " ".join([msg.get("content", "") for msg in messages if msg.get("role") == "user"])

    is_malicious, reasoning = inspect_input(full_prompt_context)
    if is_malicious:
        log_security_event(
